    OAuth: { module: "oauth", title: "OAuth clients", description: "Configure authorized redirect URIs, scopes, and environment-specific OAuth clients.", createLabel: "Create OAuth client" },
    SDKs: { module: "sdk", title: "SDKs", description: "Manage approved FinCare SDK configuration for customer applications.", createLabel: "Add SDK configuration" },
    "API Documentation": { module: "api_documentation", title: "API documentation", description: "Maintain API reference and integration guides for customer developers.", createLabel: "Add API document" },
    Webhooks: { module: "webhook", title: "Webhooks", description: "Configure FinCare event delivery for customer applications. Signing-secret values are not displayed in plaintext.", createLabel: "Add webhook" },
    Sandbox: { module: "sandbox", title: "Sandbox testing", description: "Test FinCare APIs, applications, SDKs, and integrations with isolated sandbox data and credentials.", createLabel: "Create test scenario" },
