  const records = trpc.bankPortal.administration.list.useQuery({ module: definition.module, environment }); const save = trpc.bankPortal.customerControls.saveSetting.useMutation({ onSuccess: async () => { await utils.bankPortal.administration.list.invalidate({ module: definition.module, environment }); setName(""); setValue(""); setRationale(""); toast("Setting saved", { description: `${definition.title} were updated in ${environment}.` }); } });
  const [name, setName] = useState(""); const [value, setValue] = useState(""); const [rationale, setRationale] = useState("");
